//! The size ceiling of a source file, a rule of `cargo xtask rules` (docs/design/04-architecture.md §13.3): no Rust file
//! of the repository is longer than [`CEILING`] lines, so a file that reaches it is split, by what its parts do, in the
//! change that makes it grow. A file a generator writes (its head says `@generated` or "Generated by `cargo xtask`")
//! is read by no one and is not bound; the files named in [`WAITING`] wait for the change named beside them.

/// The most lines of a source file: above the largest file of the step that split the files read most, and below
/// the largest of the long tail that stood beside them, which were split to it.
pub(crate) const CEILING: usize = 3_000;

/// The files over the ceiling that wait for a change that rewrites them, each with that change.
const WAITING: &[(&str, &str)] = &[(
    "crates/ew-schema/src/asset.rs",
    "its split waits for item X2 of the owner's list, which changes it (docs/plan/m3.5-architecture.md §4)",
)];

/// The violations among `files` (path and bytes): each Rust file over the ceiling, with its length.
pub(crate) fn check(files: &[(String, Vec<u8>)]) -> Vec<String> {
    files
        .iter()
        .filter(|(path, _)| path.ends_with(".rs"))
        .filter(|(path, _)| !WAITING.iter().any(|(w, _)| w == path))
        .filter_map(|(path, bytes)| {
            let text = String::from_utf8_lossy(bytes);
            let head: String = text.lines().take(12).collect::<Vec<_>>().join("\n");
            let generated = head.contains("@generated") || head.contains("Generated by `cargo xtask");
            let lines = text.lines().count();
            (!generated && lines > CEILING).then(|| {
                format!(
                    "{path}: {lines} lines, over the ceiling of {CEILING}; split it by what its parts do (a move, a \
                     commit of its own)"
                )
            })
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::{CEILING, check};

    /// A file over the ceiling is named with its length; one at it, a generated one and a waiting one are not.
    #[test]
    fn a_file_over_the_ceiling_is_named() {
        let long = |head: &str, n: usize| format!("{head}\n{}", "x\n".repeat(n - 1)).into_bytes();
        let files = vec![
            ("crates/a/src/big.rs".to_owned(), long("//! Big.", CEILING + 1)),
            ("crates/a/src/full.rs".to_owned(), long("//! Full.", CEILING)),
            ("crates/a/src/table.rs".to_owned(), long("// @generated by a test", CEILING + 5)),
            ("crates/ew-schema/src/asset.rs".to_owned(), long("//! Assets.", CEILING + 9)),
            ("docs/long.md".to_owned(), long("# Long", CEILING + 9)),
        ];
        assert_eq!(
            check(&files),
            [format!(
                "crates/a/src/big.rs: {} lines, over the ceiling of {CEILING}; split it by what its parts do (a \
                 move, a commit of its own)",
                CEILING + 1
            )]
        );
    }
}
